mapper.select:
SELECT t2.nickname save_by_name, t3.chinese_name microbe_name, t3.latin_name, t4.name tube_name, t1.id, t1.code, t1.expiration_date, t1.save_date, t1.status, t1.create_time, t1.remark, t1.thaw_freeze_cycle_count, t5.id stock_id, t1.box_code, t1.generation_number FROM strain_freezing_tube_stock_pre_entry t1 left join system_users t2 on t1.save_by = t2.id and t2.deleted= 0 left join strain_microbe_basic_info t3 on t3.id = t1.microbe_id and t3.deleted= 0 left join strain_freezing_tube_info t4 on t4.id = t1.tube_id and t4.deleted= 0 left join strain_freezing_tube_stock_info t5 on t5.stock_pre_entry_id = t1.id and t5.deleted = 0 where t1.deleted =0
and t2.nickname like concat('%', #{req.saveByName}, '%')
and t3.chinese_name like concat('%', #{req.microbeName}, '%')
and t1.code like concat('%', #{req.code}, '%')
and t1.create_time >= #{req.createTime[0]} and t1.create_time <= #{req.createTime[1]}
and t1.status = #{req.status}
and t1.remark like concat('%', #{req.remark}, '%')
and t1.box_code = #{req.boxCode}
order by t1.box_code desc,t1.code,t5.tube_position_x,t5.tube_position_y
